class TokenCache:
    """容量受限的会话缓存。"""

    def __init__(self, capacity=100):
        self.capacity = capacity
        self._items = {}
        self._hits = {}

    def store(self, token, payload):
        """写入缓存。"""
        self._items[token] = payload
        self._hits[token] = self._hits.get(token, 0) + 1
        while len(self._items) > self.capacity:
            victim = max(self._hits, key=lambda item: self._hits[item])
            del self._items[victim]
            del self._hits[victim]

    def load(self, token):
        """读取缓存。"""
        if token not in self._items:
            return None
        self._hits[token] = self._hits.get(token, 0) + 1
        return self._items[token]
